package com.chahinaz.pos.operations;import jakarta.validation.Valid;import java.util.UUID;import org.springframework.http.HttpStatus;import org.springframework.security.core.Authentication;import org.springframework.web.bind.annotation.*;@RestController @RequestMapping("/api/management/sales")public class ReturnController{private final ReturnService service;public ReturnController(ReturnService s){service=s;}@PostMapping("/{id}/returns")@ResponseStatus(HttpStatus.CREATED)public ReturnService.View create(@PathVariable UUID id,@Valid @RequestBody ReturnService.Input in,Authentication a){return service.create(id,in,a);}}
